import assert from "node:assert/strict";
import test from "node:test";
import { readFileSync } from "node:fs";
import { Prisma, PrismaClient } from "@prisma/client";
import { PrismaPg } from "@prisma/adapter-pg";
import { PGlite } from "@electric-sql/pglite";
import { PGLiteSocketServer } from "@electric-sql/pglite-socket";
import type { PlanningContext } from "../src/lib/planejamento/access";
import { addAllocatedPlanningRevenue, addApprovedPlanningLine, addPlanningAction, addPlanningLine, addPlanningProgram, addPlanningTransfer, configurePlanningEntity, createPlanningInstrument, getPlanningInstrument } from "../src/lib/planejamento/service";
import { saveRevenueAllocation } from "../src/lib/planejamento/catalog";
import { decideCommunityDemand, registerCommunityDemand, registerPlanningHearing } from "../src/lib/planejamento/hearings";
import { importPlanningLines } from "../src/lib/planejamento/imports";
import { getPlanningMovementHistory, registerPlanningMovement } from "../src/lib/planejamento/revisions";
